    public StaticArg boundsFor(StaticParam sp) {
        // A size has no bound to erase to; it stands for itself.
        if (sp.getKind() instanceof KindNat || sp.getKind() instanceof KindInt) {
            return STypesUtil.staticParamToArg(sp);
        }
        List<BaseType> tl = sp.getExtendsClause();
        if (tl.size() == 0) {
            return NodeFactory.makeTypeArg(NodeFactory.makeTraitType(
                    NodeFactory.makeId(sp.getInfo().getSpan(),
                            Option.<APIName>some(NamingCzar.fortressLibrary()), "Object")));
        } else if (tl.size() == 1) {
            return NodeFactory.makeTypeArg(tl.get(0));
        } else {
            return NodeFactory.makeTypeArg(NodeFactory.makeIntersectionType(tl));
        }
    }

    case (SFnHeader(sparamsL, modsL, _, whereL, throwsL, contractL,
                    paramsL, retTyL),
          SFnHeader(sparamsR, modsR, _, whereR, throwsR, contractR,
                    paramsR, retTyR)) =>
      (equalListStaticParams(sparamsL, sparamsR) &&
        ( if (ignoreAbstract)
            modsL.remove(Modifiers.Abstract).equals(modsR.remove(Modifiers.Abstract))
          else modsL.equals(modsR) ) &&
      equalOptListTypes(throwsL, throwsR) &&
      equalListParams(paramsL, paramsR) && equalOptTypes(retTyL, retTyR))
}

/* Returns true if two lists of static parameters are same. */
private def equalListStaticParams(left: List[StaticParam],
                                  right: List[StaticParam]): Boolean =
  left.length == right.length &&
  (left, right).zipped.forall((l,r) => equalStaticParams(l,r))

/* Returns true if two static parameters are same. */
private def equalStaticParams(left: StaticParam, right: StaticParam): Boolean =
  (left, right) match {
    case (SStaticParam(_, varianceL, nameL, extendsL, dominatesL, dimL, absorbsL, kindL, _),
          SStaticParam(_, varianceR, nameR, extendsR, dominatesR, dimR, absorbsR, kindR, _)) =>
      equalIdOrOps(nameL, nameR) && varianceL == varianceR && equalListTypes(extendsL, extendsR) &&
      equalListTypes(dominatesL, dominatesR) &&
      equalOptTypes(dimL, dimR) && 
      absorbsL == absorbsR && kindL == kindR
  }

/* Returns true if two lists of static arguments are same. */
private def equalListStaticArgs(left: List[StaticArg],
                                right: List[StaticArg]): Boolean =
  left.length == right.length &&
  (left, right).zipped.forall((l,r) => equalStaticArgs(l,r))

/* Returns true if two static arguments are same. */
private def equalStaticArgs(left: StaticArg, right: StaticArg): Boolean =
  (left, right) match {
    case (STypeArg(_, liftedL, typeL), STypeArg(_, liftedR, typeR)) =>
      equalTypes(typeL, typeR) && liftedL == liftedR
    case (SIntArg(_, liftedL, intL), SIntArg(_, liftedR, intR)) =>
      equalIntExprs(intL,intR) && liftedL == liftedR
    case _ => false
  }

/* Returns true if two IntExprs are same.
 * Not implemented!
 */
private def equalIntExprs(left: IntExpr, right: IntExpr): Boolean = false

/* Returns true if two parameters are same. */
private def equalParams(left: Param, right: Param): Boolean =
  (left, right) match {
    case (SParam(_, nameL, modsL, typeL, initL, varargsL),
          SParam(_, nameR, modsR, typeR, initR, varargsR)) =>
      modsL.equals(modsR) &&
      ((typeL, typeR) match {
         case (Some(tl@SType(_)), Some(tr@SType(_))) => equalTypes(tl, tr)
         case _ => false
       }) &&
      equalOptTypes(varargsL, varargsR)

        // Replace the domain (and range if not given too) with unknown types.
        val SArrowType(info, _, _, effect, io, methodInfo) = arrow
        val domain = Types.UNKNOWN
        val range = toOption(NU.getReturnType(unchecked)).getOrElse(Types.UNKNOWN)
        SArrowType(info, domain, range, effect, io, methodInfo)
    }
    val sargs = getStaticArgsFromApp(app).getOrElse(Nil)
    NotApplicableError(arrow, sargs, argTypes)
  }

  def makeNoContextError(arrow: ArrowType, infSargs: List[StaticArg]) = {
    // Gather up the static params that correspond to uninferred static args.
    val missing = (infSargs zip getStaticParams(arrow)) flatMap {
      case (STypeArg(_, false, _:_InferenceVarType), sparam) => Some(sparam)
      case _ => None
    }
    NoContextError(arrow, missing)
  }

  /** Create a FnInferenceError for this application. */
  def makeFnInferenceError(arrow: ArrowType,
                           errors: List[FnInferenceErrorKind]) = {
    val sargs = getStaticArgsFromApp(app).getOrElse(Nil)
    FnInferenceError(arrow, sargs, errors)
  }

  /** Create a ParameterError with the given FnExpr. */
  def makeParameterError(expr: FnExpr) = ParameterError(expr)

  /** Create a BodyError with the given FnExpr and static error. */
  def makeBodyError(expr: FnExpr, domain: Type, error: StaticError) =
    BodyError(expr, domain, error)
}

/** Base class for an exception for a particular overloading. */
sealed abstract class OverloadingError extends TypeError

/** This overloading is not applicable to the argument type. */
case class NotApplicableError(arrow: ArrowType,
                              sargs: List[StaticArg],
                              argTypes: List[Type])
    extends OverloadingError {

  override def toString =
    "%s is not applicable to %s %s.".
      format(OverloadingError.getSignature(sargs, arrow),
             if (argTypes.exists(hasUnknownType))
               "any type of the form"
             else
               "an argument of type",
             OverloadingError.argTypesToString(argTypes))
}

/** We could not infer all the static arguments of this overloading. */
case class NoContextError(arrow: ArrowType,
                          sparams: List[StaticParam])
    extends OverloadingError {

  override def toString = {
    val missingStr = sparams.mkString(", ")
    val plural = if (sparams.length == 1) "" else "s"
    "Could not infer static argument%s %s without context.".format(plural, missingStr)
  }
}

/** An error relating to the inferred domain type of a FnExpr. */
case class FnInferenceError(arrow: ArrowType,
                            sargs: List[StaticArg],
                            errors: List[FnInferenceErrorKind])
    extends OverloadingError {

  override def toString = {
    val sortedErrors = errors.sortWith((x,y) => x.toString < y.toString)
    val subs = sortedErrors.map(e => "%s".format(e.toString)).mkString("\n")
    "%s:\n%s".format(OverloadingError.getSignature(sargs, arrow), subs)
  }

